592	  // LocalStorage
593	  saveBestScore() {
594	    try {
595	      localStorage.setItem('game2048_best', this.bestScore);
596	    } catch (e) {}
597	  }
598	
599	  loadBestScore() {
600	    try {
601	      const saved = localStorage.getItem('game2048_best');
602	      if (saved !== null) this.bestScore = parseInt(saved, 10) || 0;
603	    } catch (e) {}
604	  }
605	
606	  // Input
607	  bindEvents() {
608	    document.addEventListener('keydown', (e) => {
609	      const map = {
610	        ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
611	        w: 'up', W: 'up', s: 'down', S: 'down', a: 'left', A: 'left', d: 'right', D: 'right',
612	      };
613	      const dir = map[e.key];
614	      if (dir) {
615	        e.preventDefault();
616	        this.move(dir);
617	      }
618	    });
619	
620	    let touchStartX = 0, touchStartY = 0;
621	    const board = document.getElementById('board');
622	
623	    board.addEventListener('touchstart', (e) => {
624	      touchStartX = e.touches[0].clientX;
625	      touchStartY = e.touches[0].clientY;
626	    }, { passive: true });
627	
628	    board.addEventListener('touchend', (e) => {
629	      const dx = e.changedTouches[0].clientX - touchStartX;
630	      const dy = e.changedTouches[0].clientY - touchStartY;
631	      const absDx = Math.abs(dx);
632	      const absDy = Math.abs(dy);
633	      const threshold = 30;
634	
635	      if (Math.max(absDx, absDy) < threshold) return;
636	
637	      if (absDx > absDy) {
638	        this.move(dx > 0 ? 'right' : 'left');
639	      } else {
640	        this.move(dy > 0 ? 'down' : 'up');
641	      }
642	    });
643	
644	    document.getElementById('restartBtn').addEventListener('click', () => this.reset());
645	    document.getElementById('overlayBtn').addEventListener('click', () => this.reset());
646	  }
647	}
