241	class Game {
242	  constructor() {
243	    this.size = 4;
244	    this.board = [];
245	    this.score = 0;
246	    this.bestScore = 0;
247	    this.gameOver = false;
248	    this.won = false;
249	    this.keepPlaying = false;
250	    this.tiles = {}; // key: "r,c" -> { value, merged, isNew }
251	    this.nextId = 0;
252	
253	    this.tileContainer = document.getElementById('tileContainer');
254	    this.scoreEl = document.getElementById('score');
255	    this.bestEl = document.getElementById('best');
256	    this.bestBox = document.getElementById('bestBox');
257	    this.overlay = document.getElementById('overlay');
258	    this.overlayText = document.getElementById('overlayText');
259	
