267	
268	  init() {
269	    this.board = Array.from({ length: this.size }, () => Array(this.size).fill(0));
270	    this.score = 0;
271	    this.gameOver = false;
272	    this.won = false;
273	    this.keepPlaying = false;
274	    this.tiles = {};
275	    this.nextId = 0;
276	    this.spawn();
277	    this.spawn();
278	    this.updateScore();
279	    this.overlay.classList.add('hidden');
280	  }
281	
282	  reset() {
283	    this.init();
284	    this.render();
285	  }
286	
287	  spawn() {
288	    const empty = [];
289	    for (let r = 0; r < this.size; r++) {
290	      for (let c = 0; c < this.size; c++) {
291	        if (this.board[r][c] === 0) empty.push({ r, c });
292	      }
293	    }
294	    if (empty.length === 0) return;
295	    const { r, c } = empty[Math.floor(Math.random() * empty.length)];
296	    const value = Math.random() < 0.9 ? 2 : 4;
297	    this.board[r][c] = value;
298	    this.tiles[`${r},${c}`] = { value, merged: false, isNew: true, id: this.nextId++ };
299	  }
300	
301	  move(direction) {
302	    if (this.gameOver) return;
303	    if (this.won && !this.keepPlaying) return;
304	
305	    const vectors = { up: [-1, 0], down: [1, 0], left: [0, -1], right: [0, 1] };
306	    const [dr, dc] = vectors[direction];
307	    let moved = false;
308	    let newBoard = Array.from({ length: this.size }, () => Array(this.size).fill(0));
309	    let newTiles = {};
310	    const mergedPairs = new Set();
311	
312	    // Reset tile states
313	    for (const key in this.tiles) {
314	      this.tiles[key].merged = false;
315	      this.tiles[key].isNew = false;
316	    }
317	
318	    const isHorizontal = direction === 'left' || direction === 'right';
319	    const reverse = direction === 'down' || direction === 'right';
320	
321	    for (let i = 0; i < this.size; i++) {
322	      let line = [];
323	      for (let j = 0; j < this.size; j++) {
324	        const r = isHorizontal ? i : j;
325	        const c = isHorizontal ? j : i;
326	        line.push(this.board[r][c]);
327	      }
328	      if (reverse) line.reverse();
329	
330	      const result = this.processLine(line, i, isHorizontal, reverse, mergedPairs);
331	      if (result.changed) moved = true;
332	
333	      // Build new tiles from result
334	      for (const item of result.items) {
335	        const actualPos = isHorizontal ? { r: i, c: item.pos } : { r: item.pos, c: i };
336	        if (reverse) {
337	          if (isHorizontal) actualPos.c = this.size - 1 - item.pos;
338	          else actualPos.r = this.size - 1 - item.pos;
339	        }
340	        newBoard[actualPos.r][actualPos.c] = item.value;
341	        const key = `${actualPos.r},${actualPos.c}`;
342	        const oldTile = this.tiles[key];
343	        if (item.fromMerged) {
344	          newTiles[key] = { value: item.value, merged: true, isNew: false, id: this.nextId++ };
345	        } else if (item.fromPos !== null) {
346	          const oldKey = `${item.fromR},${item.fromC}`;
347	          if (oldTile && oldTile.id === this.tiles[oldKey]?.id) {
348	            newTiles[key] = { ...oldTile, merged: false, isNew: false };
349	          } else {
350	            newTiles[key] = { value: item.value, merged: false, isNew: false, id: this.nextId++ };
351	          }
352	        } else {
353	          newTiles[key] = { value: item.value, merged: false, isNew: false, id: this.nextId++ };
354	        }
355	      }
356	    }
357	
358	    this.board = newBoard;
359	    this.tiles = newTiles;
360	
361	    if (moved) {
362	      this.spawn();
363	      this.render();
364	      this.playSound('move');
365	
366	      if (this.checkWin() && !this.won) {
367	        this.won = true;
368	        this.playSound('win');
369	      }
370	      if (this.checkGameOver()) {
371	        this.gameOver = true;
372	        this.playSound('lose');
373	      }
374	    }
375	  }
376	
377	  processLine(line, lineIndex, isHorizontal, reverse, mergedPairs) {
378	    let items = [];
379	    let changed = false;
380	    let pos = 0;
381	
382	    // First pass: collect non-zero values with their original positions
383	    let values = [];
384	    for (let j = 0; j < line.length; j++) {
385	      if (line[j] !== 0) {
386	        const origPos = reverse ? this.size - 1 - j : j;
387	        values.push({ value: line[j], r: isHorizontal ? lineIndex : j, c: isHorizontal ? j : lineIndex, origPos: reverse ? this.size - 1 - j : j });
388	      }
389	    }
390	
391	    // Merge pass
392	    let i = 0;
393	    let mergedAt = new Set();
394	    while (i < values.length) {
395	      if (i + 1 < values.length && values[i].value === values[i + 1].value) {
396	        const newValue = values[i].value * 2;
397	        this.score += newValue;
398	        items.push({
399	          value: newValue,
400	          pos: pos++,
401	          fromMerged: true,
402	          fromPos: null,
403	          fromR: -1,
404	          fromC: -1
405	        });
406	        mergedAt.add(i);
407	        mergedAt.add(i + 1);
408	        i += 2;
409	        changed = true;
410	      } else {
411	        const origPos = reverse ? this.size - 1 - values[i].origPos : values[i].origPos;
412	        const newPos = pos++;
413	        if (newPos !== origPos) changed = true;
414	        items.push({
415	          value: values[i].value,
416	          pos: newPos,
417	          fromMerged: false,
418	          fromPos: origPos,
419	          fromR: values[i].r,
420	          fromC: values[i].c
421	        });
422	        i++;
423	      }
424	    }
425	
426	    if (values.length > 0 && items.length !== values.length) changed = true;
427	
428	    return { items, changed };
429	  }
430	
431	  checkWin() {
432	    if (this.won) return false;
433	    for (let r = 0; r < this.size; r++) {
434	      for (let c = 0; c < this.size; c++) {
435	        if (this.board[r][c] >= 2048) return true;
436	      }
437	    }
438	    return false;
439	  }
440	
441	  checkGameOver() {
442	    for (let r = 0; r < this.size; r++) {
443	      for (let c = 0; c < this.size; c++) {
444	        if (this.board[r][c] === 0) return false;
445	        if (r < this.size - 1 && this.board[r][c] === this.board[r + 1][c]) return false;
446	        if (c < this.size - 1 && this.board[r][c] === this.board[r][c + 1]) return false;
447	      }
448	    }
449	    return true;
450	  }
451	
452	  updateScore() {
453	    this.scoreEl.textContent = this.score;
454	    if (this.score > this.bestScore) {
455	      this.bestScore = this.score;
456	      this.saveBestScore();
457	      this.bestBox.classList.add('new-record');
458	      setTimeout(() => this.bestBox.classList.remove('new-record'), 600);
459	    }
460	    this.bestEl.textContent = this.bestScore;
461	  }
462	
463	  render() {
464	    this.tileContainer.innerHTML = '';
465	    const boardEl = document.getElementById('board');
466	    const boardWidth = boardEl.clientWidth;
467	    const gap = boardWidth <= 400 ? 8 : 12;
468	    const padding = gap;
469	    const cellSize = (boardWidth - padding * 2 - gap * (this.size - 1)) / this.size;
470	
471	    const colors = {
472	      2:    { bg: '#eee4da', fg: '#776e65' },
473	      4:    { bg: '#ede0c8', fg: '#776e65' },
474	      8:    { bg: '#f2b179', fg: '#f9f6f2' },
475	      16:   { bg: '#f59563', fg: '#f9f6f2' },
476	      32:   { bg: '#f67c5f', fg: '#f9f6f2' },
477	      64:   { bg: '#f65e3b', fg: '#f9f6f2' },
478	      128:  { bg: '#edcf72', fg: '#f9f6f2' },
479	      256:  { bg: '#edcc61', fg: '#f9f6f2' },
480	      512:  { bg: '#edc850', fg: '#f9f6f2' },
481	      1024: { bg: '#edc53f', fg: '#f9f6f2' },
482	      2048: { bg: '#edc22e', fg: '#f9f6f2' },
483	      4096: { bg: '#3c3a32', fg: '#f9f6f2' },
484	      8192: { bg: '#3c3a32', fg: '#f9f6f2' },
485	    };
486	
487	    for (const key in this.tiles) {
488	      const tile = this.tiles[key];
489	      const [r, c] = key.split(',').map(Number);
490	      const x = padding + c * (cellSize + gap);
491	      const y = padding + r * (cellSize + gap);
492	      const color = colors[tile.value] || colors[8192];
493	      const fontSize = tile.value >= 10000 ? '24px' :
494	                       tile.value >= 1000 ? '32px' :
495	                       tile.value >= 100 ? '38px' : '44px';
496	
497	      const el = document.createElement('div');
498	      el.className = 'tile';
499	      if (tile.merged) el.classList.add('merged');
500	      if (tile.isNew) el.classList.add('new-tile');
501	      el.style.cssText = `
502	        width: ${cellSize}px;
503	        height: ${cellSize}px;
504	        transform: translate(${x}px, ${y}px);
505	        background: ${color.bg};
506	        color: ${color.fg};
507	        font-size: ${fontSize};
508	      `;
509	      el.textContent = tile.value;
510	      this.tileContainer.appendChild(el);
511	    }
512	
513	    this.updateScore();
514	
515	    // Show overlay
516	    if (this.gameOver) {
517	      this.overlayText.textContent = '游戏结束';
518	      this.overlay.classList.remove('hidden');
519	    } else if (this.won && !this.keepPlaying) {
520	      this.overlayText.textContent = '你赢了！';
521	      this.overlay.classList.remove('hidden');
522	    }
523	  }
524	
525	  // Audio
526	  getAudioContext() {
527	    if (!this.audioCtx) {
528	      this.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
529	    }
530	    return this.audioCtx;
531	  }
532	
533	  playSound(type) {
534	    try {
535	      const ctx = this.getAudioContext();
536	      if (ctx.state === 'suspended') ctx.resume();
537	
538	      if (type === 'move') {
539	        const osc = ctx.createOscillator();
540	        const gain = ctx.createGain();
541	        osc.connect(gain);
542	        gain.connect(ctx.destination);
543	        osc.type = 'sine';
544	        osc.frequency.value = 200;
545	        gain.gain.setValueAtTime(0.15, ctx.currentTime);
546	        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
547	        osc.start(ctx.currentTime);
548	        osc.stop(ctx.currentTime + 0.05);
549	      } else if (type === 'merge') {
550	        const osc = ctx.createOscillator();
551	        const gain = ctx.createGain();
552	        osc.connect(gain);
553	        gain.connect(ctx.destination);
554	        osc.type = 'sine';
555	        osc.frequency.value = 400;
556	        gain.gain.setValueAtTime(0.2, ctx.currentTime);
557	        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
558	        osc.start(ctx.currentTime);
559	        osc.stop(ctx.currentTime + 0.1);
560	      } else if (type === 'win') {
561	        [523, 659, 784, 1047].forEach((freq, i) => {
562	          const osc = ctx.createOscillator();
563	          const gain = ctx.createGain();
564	          osc.connect(gain);
565	          gain.connect(ctx.destination);
566	          osc.type = 'sine';
567	          osc.frequency.value = freq;
568	          gain.gain.setValueAtTime(0.15, ctx.currentTime + i * 0.12);
569	          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.12 + 0.2);
570	          osc.start(ctx.currentTime + i * 0.12);
571	          osc.stop(ctx.currentTime + i * 0.12 + 0.2);
572	        });
573	      } else if (type === 'lose') {
574	        [300, 250, 200, 150].forEach((freq, i) => {
575	          const osc = ctx.createOscillator();
576	          const gain = ctx.createGain();
577	          osc.connect(gain);
578	          gain.connect(ctx.destination);
579	          osc.type = 'sawtooth';
580	          osc.frequency.value = freq;
581	          gain.gain.setValueAtTime(0.1, ctx.currentTime + i * 0.15);
582	          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.15 + 0.2);
583	          osc.start(ctx.currentTime + i * 0.15);
584	          osc.stop(ctx.currentTime + i * 0.15 + 0.2);
585	        });
586	      }
587	    } catch (e) {
588	      // Silently ignore audio errors
589	    }
590	  }
