```javascript
move(direction) {
  if (this.gameOver) return;
  if (this.won && !this.keepPlaying) return;

  const oldBoard = this.board.map(row => [...row]);
  this.mergedPositions = new Set();

  // Clear board
  for (let r = 0; r < 4; r++)
    for (let c = 0; c < 4; c++)
      this.board[r][c] = 0;

  const vectors = {
    up: { rowStep: 1, colStep: 0, start: 0, end: 4 },
    down: { rowStep: -1, colStep: 0, start: 3, end: -1 },
    left: { rowStep: 0, colStep: 1, start: 0, end: 4 },
    right: { rowStep: 0, colStep: -1, start: 3, end: -1 },
  };

  const v = vectors[direction];
  const isHorizontal = v.colStep !== 0;
  const lineCount = 4;

  for (let line = 0; line < lineCount; line++) {
    // Extract values from this line in traversal order
    let values = [];
    for (let i = v.start; i !== v.end; i += v.end > v.start ? 1 : -1) {
      const r = isHorizontal ? line : i;
      const c = isHorizontal ? i : line;
      if (oldBoard[r][c] !== 0) {
        values.push(oldBoard[r][c]);
      }
    }

    // Merge
    let result = [];
    let resultPos = 0;
    let valueIdx = 0;
    while (valueIdx < values.length) {
      if (valueIdx + 1 < values.length && values[valueIdx] === values[valueIdx + 1]) {
        const merged = values[valueIdx] * 2;
        result.push(merged);
        this.score += merged;
        // Track merged position
        const r = isHorizontal ? line : (v.start + resultPos * (v.end > v.start ? 1 : -1));
        const c = isHorizontal ? (v.start + resultPos * (v.end > v.start ? 1 : -1)) : line;
        this.mergedPositions.add(`${r},${c}`);
        resultPos++;
        valueIdx += 2;
      } else {
        result.push(values[valueIdx]);
        resultPos++;
        valueIdx++;
      }
    }

    // Place results back
    for (let i = 0; i < result.length; i++) {
      const pos = v.start + i * (v.end > v.start ? 1 : -1);
      const r = isHorizontal ? line : pos;
      const c = isHorizontal ? pos : line;
      this.board[r][c] = result[i];
    }
  }

  // Check if board changed
  let moved = false;
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 4; c++) {
      if (this.board[r][c] !== oldBoard[r][c]) {
        moved = true;
        break;
      }
    }
    if (moved) break;
  }

  if (!moved) return;

  // Spawn
  this.newPosition = null;
  const empty = [];
  for (let r = 0; r < 4; r++)
    for (let c = 0; c < 4; c++)
      if (this.board[r][c] === 0) empty.push({r, c});

  if (empty.length > 0) {
    const {r, c} = empty[Math.floor(Math.random() * empty.length)];
    this.board[r][c] = Math.random() < 0.9 ? 2 : 4;
    this.newPosition = `${r},${c}`;
  }

  this.render();
  // Check for merge sound
  if (this.mergedPositions.size > 0) {
    this.playSound('merge');
  } else {
    this.playSound('move');
  }

  if (this.checkWin() && !this.won) {
    this.won = true;
    this.playSound('win');
  }
  if (this.checkGameOver()) {
    this.gameOver = true;
    this.playSound('lose');
  }
}
